<template><section v-if="summary.signedCount" class="verification-summary" :class="{'verification-summary--error':summary.changed||summary.failedProof}" aria-label="Verification results"><h3>{{ summary.changed ? t('libresign','Document integrity check failed') : summary.failedProof ? t('libresign','Signature validity needs review') : summary.integrity ? t('libresign','Signed content integrity verified') : t('libresign','Verification is incomplete') }}</h3><p v-if="summary.changed"><strong>{{ t('libresign','Signed content or a signature has changed, or its integrity could not be verified. Review the technical details before relying on this document.') }}</strong></p><p v-else-if="summary.integrity">{{ t('libresign','The signed content passed its integrity checks. Certificate expiry is a separate check and does not mean the document was altered.') }}</p><p v-if="summary.failedProof && !summary.changed" role="alert"><strong>{{ t('libresign','Some signature validity checks failed. Review the verification details before relying on this document.') }}</strong></p><dl><div><dt>{{ t('libresign','Signing identity') }}</dt><dd>{{ summary.trusted ? t('libresign','Trusted by this LibreSign installation') : t('libresign','Issuer trust requires review') }}</dd></div><div><dt>{{ t('libresign','Signing time') }}</dt><dd>{{ summary.timestampVerified ? t('libresign','Timestamp verified against configured trust authorities') : t('libresign','Historical signing time has not been independently verified') }}</dd></div><div><dt>{{ t('libresign','Long-term verification') }}</dt><dd><strong>{{ summary.longTerm ? t('libresign','PAdES-LT evidence verified from the PDF') : t('libresign','Long-term validity has not been established') }}</strong></dd></div><div v-if="summary.expired"><dt>{{ t('libresign','Certificate expiry') }}</dt><dd>{{ summary.longTerm ? t('libresign','A signing certificate has expired. Historical validity was verified using the retained evidence.') : t('libresign','A signing certificate has expired. Expiry alone does not indicate a changed document; historical validity needs sufficient evidence.') }}</dd></div></dl><p class="verification-scope">{{ t('libresign','Trust is assessed against the authorities configured for this installation. Other PDF readers may use different trust lists.') }}</p></section></template>
<script setup lang="ts">
import {computed} from 'vue'
import {t} from '@nextcloud/l10n'
import {verificationSummary,type LongTermValidation} from '../../services/verificationSummary'
const props=defineProps<{document:{signers?:Parameters<typeof verificationSummary>[0],longTermValidation?:LongTermValidation}}>()
const summary=computed(()=>verificationSummary(props.document.signers||[],props.document.longTermValidation))
</script>
<style scoped>.verification-summary{padding:22px;border:1px solid var(--color-border);border-inline-start:5px solid var(--color-primary-element);border-radius:12px;margin-bottom:22px;background:var(--color-background-hover)}.verification-summary--error{border-inline-start-color:var(--color-error)}h3{font-size:20px;font-weight:650;margin-bottom:10px}p{line-height:1.6}dl{margin-block:18px}dl>div{display:grid;grid-template-columns:minmax(140px,1fr) 2fr;gap:14px;border-top:1px solid var(--color-border);padding-block:12px}dt{font-weight:650}dd{margin:0;line-height:1.5}.verification-scope{font-size:13px;color:var(--color-text-maxcontrast)}@media(max-width:600px){dl>div{grid-template-columns:1fr;gap:5px}.verification-summary{padding:16px}}</style>
